tool_input.command:
node --input-type=module << 'EOF'
import * as NlSpec from './machtzev/generator/nl-spec.mjs';
import fs from 'fs';

const spec = fs.readFileSync('machtzev/generator/specs-ds/tasks.txt', 'utf8');
const parsed = NlSpec.nlToSpec(spec);

console.log('✓ Entities parsed:');
parsed.entities.forEach(e => {
  console.log('  -', e.name, 'fields:', e.fields.map(f => f.name).join(', '));
});

console.log('\n✓ Particles parsed:');
parsed.particles.forEach(p => {
  console.log('  -', p.entityName + ':', p.shape);
});
EOF

